import React, { Component, Fragment } from "react";
import { MDBDataTable } from "mdbreact";
import { Card, CardBody, CardHeader } from "reactstrap";

class DatatablePageCopy extends Component {
  render() {
    const data = {
      columns: [
        {
          label: "Name",
          field: "name",
          sort: "asc",
          width: 150
        },
        {
          label: "Position",
          field: "position",
          sort: "asc",
          width: 270
        },
        {
          label: "Office",
          field: "office",
          sort: "asc",
          width: 200
        },
        {
          label: "Age",
          field: "age",
          sort: "asc",
          width: 100
        },
        {
          label: "Start date",
          field: "date",
          sort: "asc",
          width: 150
        },
        {
          label: "Salary",
          field: "salary",
          sort: "asc",
          width: 100
        }
      ],
      rows: [
        {
          name: "Tiger Nixon",
          position: "System Architect",
          office: "Edinburgh",
          age: "61",
          date: "2011/04/25",
          salary: "$320"
        },
        {
          name: "Garrett Winters",
          position: "Accountant",
          office: "Tokyo",
          age: "63",
          date: "2011/07/25",
          salary: "$170"
        }
      ]
    };

    return (
      <Card>
        <CardHeader>
          <h4>Clients</h4>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}
export default DatatablePageCopy;
